export function contentPages(data, {number,esc,badge,heading,note}) {
  const sourceExplanation = 'The original export label “Reliable Multi-Date Observation” identifies cells with at least three sampled dates. Their temperature summaries come from V5 predictions at satellite-sampled locations, not directly from measured LST. Limited and Model Only cells use complete-grid V5 predictions; the limited group has one or two sampled dates of historical support.';
  const card = (label,title,body) => `<article class="panel content-card"><div class="section-label">${label}</div><h2>${title}</h2>${body}</article>`;
  const bar = (label,value,width,color='#327655') => `<div><div class="score-bar-label"><span>${label}</span><strong>${value}</strong></div><div class="score-bar-track"><div class="score-bar-fill" style="--width:${width}%;--color:${color}"></div></div></div>`;
  const s = data.project_summary;
  function hotspots(){const c=data.hotspot_clusters[0];return heading('The places to prioritize.','Connected hotspots ranked by scale, heat persistence and evidence.','73 CONNECTED HOTSPOT CLUSTERS')+`<section class="cluster-highlight"><div><div class="eyebrow">PLANNING RANK 01 · ${esc(c.Planning_Category.toUpperCase())}</div><h2>${esc(c.Dominant_Locality)}</h2><p>The dominant locality of the largest connected hotspot. This cluster extends across multiple localities.</p><a class="button-primary" href="map.html?cluster=${c.Cluster_ID}">Explore this cluster ↗</a></div><dl class="detail-grid">${[['Cluster area',`${number(c.Cluster_Area_km2)} km²`],['Planning score',`${number(c.Planning_Significance_Score,2)} / 100`],['Mean median LST',`${number(c.Mean_Median_LST,2)} °C`],['Scenario trees',number(c.Total_Trees_To_Plant)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section><section class="panel"><div class="panel-title"><div><h2>Hotspot rankings</h2><p id="cluster-count">Top 10 by planning significance</p></div><a href="methodology.html#cluster-method">How ranking works</a></div><div class="filters"><label class="search-field"><span class="sr-only">Search hotspot localities</span><input id="cluster-search" type="search" placeholder="Search hotspot localities…" style="padding-left:13px"></label><label class="sr-only" for="cluster-sort">Rank clusters by</label><select id="cluster-sort"><option value="Planning_Rank">Planning significance</option><option value="Intensity_Rank">Heat intensity</option><option value="Cluster_Area_km2">Largest area</option></select><label class="sr-only" for="cluster-limit">Clusters to show</label><select id="cluster-limit"><option value="10">Top 10</option><option value="73">All 73 clusters</option></select></div><div class="table-scroll"><table class="cluster-table"><caption class="sr-only">Connected hotspot clusters</caption><thead><tr><th>Planning rank</th><th>Dominant locality</th><th>Category</th><th>Area</th><th>High / Very high</th><th>Mean median LST</th><th>Maximum LST</th><th>Scenario trees</th><th>Planning score</th></tr></thead><tbody id="cluster-rows"></tbody></table></div></section>${note()}<div class="content-grid section-heading">${card('HEAT INTENSITY','How hot is the cluster?',`<p>Intensity combines normalized mean heat score (40%), maximum heat score (25%), hot frequency (20%) and the share of Very High cells (15%). Small, intense clusters can rank highly.</p>`)}${card('PLANNING SIGNIFICANCE','Where should planning begin?',`<p>Planning significance also includes cluster size, the count of Very High cells and evidence strength. A single-cell extreme and a large heat corridor therefore answer different planning questions.</p>`)}</div>`}
  function renderClusters(){const q=document.querySelector('#cluster-search').value.trim().toLowerCase();const sort=document.querySelector('#cluster-sort').value;const limit=Number(document.querySelector('#cluster-limit').value);const all=data.hotspot_clusters.filter(c=>`${c.Dominant_Locality} ${c.Localities}`.toLowerCase().includes(q)).sort((a,b)=>sort==='Cluster_Area_km2'?b[sort]-a[sort]:a[sort]-b[sort]);const rows=all.slice(0,limit);document.querySelector('#cluster-count').textContent=`${rows.length} of ${all.length} matching clusters · ${sort==='Planning_Rank'?'planning significance':sort==='Intensity_Rank'?'heat intensity':'largest area'}`;document.querySelector('#cluster-rows').innerHTML=rows.length?rows.map(c=>`<tr class="${c.Planning_Rank===1?'selected':''}"><td>${String(c.Planning_Rank).padStart(2,'0')}</td><td><a href="map.html?cluster=${c.Cluster_ID}"><strong>${esc(c.Dominant_Locality)}</strong></a><small>Cluster ${c.Cluster_ID} · Intensity rank ${c.Intensity_Rank}</small></td><td>${badge(c.Planning_Category)}</td><td>${number(c.Cluster_Area_km2)} km²</td><td>${c.High_Cells} / ${c.Very_High_Cells}</td><td>${number(c.Mean_Median_LST,2)} °C</td><td>${number(c.Maximum_LST,2)} °C</td><td>${number(c.Total_Trees_To_Plant)}</td><td>${number(c.Planning_Significance_Score,2)}</td></tr>`).join(''):'<tr><td colspan="9" class="empty">No matching clusters. Try a different locality.</td></tr>'}
  function methodology(){return heading('Understand the evidence.','From satellite observations to a complete cooling-priority grid.','METHODS & VALIDATION')+`<section class="method-intro"><div><h2>A hybrid surface.<br>Transparent planning assumptions.</h2><p style="margin-top:13px">The final atlas combines earlier sample-based V5 summaries with complete-grid V5 estimates. Each cell keeps its observation-support label.</p></div><div class="method-stat-row"><div class="method-stat"><strong>25</strong><small>model features</small></div><div class="method-stat"><strong>7</strong><small>2026 dates</small></div><div class="method-stat"><strong>9,240</strong><small>grid-date predictions</small></div></div></section><div class="content-grid">${card('01 / STUDY AREA','A consistent spatial framework',`<p>The initial rectangle spans 77.45–77.75° E and 12.80–13.15° N. The final approximate 1 km grid follows the sampled footprint, reaching slightly beyond this rectangle at its edges.</p><p>Its 1,320 km² area is the analysis grid area. Localities label cell centres and do not define official Bengaluru or BBMP boundaries.</p>`)}${card('02 / INPUTS','Satellite and atmospheric context',`<p>Landsat 8 supplies LST targets and optical features. Sentinel-2 supplies NDVI. Dynamic World supplies tree and built-up probabilities. SRTM elevation and JRC surface-water distance add spatial context.</p><p>ERA5-Land and ERA5 supply weather, recent atmospheric history and conditions within ±90 minutes of satellite acquisition.</p>`)}${card('03 / PROCESSING','Mask, match and extract',`<p>Landsat QA_PIXEL cloud and cloud-shadow bits are masked; Sentinel-2 cloud and shadow classes are excluded. Reflectance and thermal scale factors are applied before extraction.</p><p>NDVI compares near-infrared with red, NDBI shortwave-infrared with near-infrared, and the final NDWI green with near-infrared. Albedo represents surface reflectivity.</p>`)}${card('04 / COVERAGE','Complete the grid carefully',`<p>Spatial features are averaged within each cell. Missing values use a same-cell median across dates, then a date median, then an overall median. Atmospheric features are matched by date.</p><p>This fills coverage gaps but introduces uncertainty and changes the spatial scale from training samples to cell averages.</p>`)}</div><h2 class="section-heading">How the model evolved</h2><section class="panel content-card"><div class="feature-list">${[['V1','7 · baseline'],['V2','11 · moisture & rain'],['V3','15 · atmospheric history'],['V4','20 · spatial context'],['V5','25 · overpass weather']].map(([v,t])=>`<span><strong>${v}</strong> &nbsp; ${t}</span>`).join('')}</div><p style="margin-top:20px">The later models use a Random Forest with 200 trees, trained on data through 2025 and evaluated on 2026 samples. V5 was selected using these comparisons; the evaluation was not an untouched final test or a spatial holdout.</p><div class="table-scroll" style="margin:20px -10px 10px"><table><caption class="sr-only">Saved model comparison on the common V5 dataset</caption><thead><tr><th>Model</th><th>Features</th><th>MAE (°C)</th><th>RMSE (°C)</th><th>R²</th></tr></thead><tbody>${data.model_metrics.models.slice().sort((a,b)=>Number(a.Features)-Number(b.Features)).map(m=>`<tr><td><strong>${esc(m.Model)}</strong></td><td>${m.Features}</td><td>${number(m.MAE,4)}</td><td>${number(m.RMSE,4)}</td><td>${number(m.R2,4)}</td></tr>`).join('')}</tbody></table></div><p class="fineprint">These are the saved, common-dataset results from the final V3–V5 comparison. Earlier V1 / V2 RMSE values reported in the handoff are 4.2332 / 3.6565 °C. The earlier V3 RMSE of 3.2322 °C comes from a different comparison and is not substituted into this table.</p><details style="margin-top:20px"><summary>All 25 V5 features</summary><div class="feature-list">${data.model_metrics.features.map(f=>`<span>${esc(f.Feature.replaceAll('_',' '))}</span>`).join('')}</div></details></section><div class="content-grid section-heading">${card('05 / HYBRID TEMPERATURE','Preserve the earlier sample-based pattern',`<p>${sourceExplanation}</p><p>The merge keeps the earlier median, maximum and frequency values where available, then recalculates a heat score and relative priority across the complete 1,320-cell grid.</p>`)}${card('06 / PERSISTENCE','A sampled seasonal picture',`<p>The seven dates run from 27 January to 3 May 2026. On the earlier surface, hot frequency is the fraction of sampled rows classified High or Very High. Multiple samples on one date can contribute.</p><p>On the complete grid, it is the fraction of the seven grid-date predictions exceeding that dataset’s hot threshold. It is not a count of every hot day or a live weather forecast.</p>`)}</div><h2 class="section-heading">From heat to cooling priority</h2><div class="content-grid">${card('07 / HEAT SCORE','Seven contributors, one relative score',`<div class="score-bars">${[['Median LST',30],['Hot frequency',25],['Low tree probability',15],['Very-hot frequency',10],['Built-up probability',10],['Distance to water',5],['Low albedo',5]].map(([k,v])=>bar(k,`${v}%`,v/30*100)).join('')}</div><p class="fineprint">Continuous spatial variables are min–max normalized across the final grid; hot-frequency terms use clipped proportions. Weighted scores are scaled to 0–100.</p>`)}${card('08 / PRIORITY CLASSES','Percentiles within the study',`<div class="score-bars">${data.priority_summary.map(p=>bar(p.Priority,`${p.Study_Area_Percent}% · ${p.Cells} cells`,p.Study_Area_Percent*2,{'Low':'#5cab7e','Moderate':'#e8c756','High':'#e79a49','Very High':'#d76b56'}[p.Priority])).join('')}</div><p>Class thresholds are the 50th, 75th and 90th percentiles of the final heat score. High + Very High therefore cover 25% of this grid by construction; they are not universal dangerous-temperature thresholds.</p>`)}</div><div class="content-grid section-heading">${card('09 / COOLING SCENARIO','Tree and non-tree interventions',`<p>Priority-specific greening ranges are Low 1–3%, Moderate 4–7%, High 8–12%, and Very High 12–18%. A need factor combines heat (40%), tree deficit (35%) and built intensity (25%).</p><p>Built probability controls the tree share: 35% at ≥0.70, 50% at ≥0.50, 70% at ≥0.30, and 85% below 0.30. Remaining cooling area is assigned to non-tree measures.</p><p><strong>Scenario trees = ceiling(tree-canopy target ÷ 30 m²)</strong>, calculated per cell and summed. The exported total is ${number(s.scenario_based_trees)}.</p>`)}${card('10 / RECOMMENDATIONS','Match the intervention to the setting',`<p>Dense cells can combine street trees, pocket parks, green or cool roofs, reflective pavement and shaded corridors. Less built-up priority cells favour canopy expansion, urban forests and park restoration.</p><p>The scenario gives approximately 40.86 km² of tree-canopy target and 38.64 km² of non-tree cooling area. It does not calculate actual temperature reductions or verify land availability.</p>`)}</div><section id="cluster-method" class="panel content-card section-heading"><div class="section-label">11 / CONNECTED HOTSPOTS</div><h2>Cluster size and evidence shape the ranking.</h2><p>High and Very High cells are connected through their eight neighbours, including diagonals. This yields 73 clusters covering 330 km². The map uses the membership produced by the clustering script.</p><div class="content-grid" style="margin-top:24px"><div><h3>Planning significance</h3><div class="score-bars">${[['Cluster area',30],['Very High cell count',20],['Mean heat score',20],['Hot frequency',10],['Maximum heat score',10],['Evidence',10]].map(([k,v])=>bar(k,`${v}%`,v/30*100)).join('')}</div></div><div class="prose"><h3>How the terms are prepared</h3><p>Area and Very High counts are log1p-transformed and min–max normalized. Mean / maximum heat scores and hot frequency are min–max normalized across clusters.</p><p>Evidence is the cell-weighted average of Strong = 1.00, Moderate = 0.75, Limited = 0.40 and Model Only = 0.20. It is an evidence score, not a confidence interval.</p><p>Planning ranks 1–5 are Critical, 6–15 Major, 16–30 Secondary, and later ranks Localized. Intensity uses 40% mean heat, 25% maximum heat, 20% hot frequency and 15% Very High share.</p></div></div></section><h2 class="section-heading">Validation and limits</h2><div class="content-grid">${card('SURFACE AGREEMENT','Two predicted surfaces differ',`<div class="method-stat-row" style="margin-top:20px"><div class="method-stat"><strong>2.50 °C</strong><small>mean absolute difference</small></div><div class="method-stat"><strong>38.05%</strong><small>priority agreement</small></div></div><p>The complete-grid surface was compared with 678 earlier persistent-analysis cells. RMSE was 3.08 °C, correlation 0.283, median absolute difference 2.36 °C, and 90th-percentile difference 4.81 °C.</p><p>These measure agreement between analysis outputs. Both surfaces are model-derived, and their original heat-score formulas differ; this is not independent ground validation.</p>`)}${card('17 APRIL 2026','A difficult prediction regime',`<div class="method-stat-row" style="margin-top:20px"><div class="method-stat"><strong>+4.86 °C</strong><small>mean prediction bias</small></div><div class="method-stat"><strong>5.69 °C</strong><small>date-level RMSE</small></div></div><p>For 363 evaluation samples, mean observed LST was 39.30 °C and mean V5 prediction was 44.16 °C. MAE was 4.90 °C. The date remains in the analysis.</p><p>Medians reduce sensitivity to individual extremes, but do not eliminate model bias or uneven sampling.</p>`)}</div><section id="interpretation" class="panel content-card section-heading"><h2>Read the atlas with these limits in mind.</h2><div class="prose"><details open><summary>Evidence strength and temperature meaning</summary><p>LST describes surface temperature, not air temperature or human heat stress. All mapped temperature summaries in this pipeline are model-derived. Strong (111 cells) and Moderate (567) retain the earlier sample-based summaries; Limited (578) and Model Only (64) use complete-grid estimates. Reliability describes sampling support, not guaranteed accuracy.</p></details><details><summary>Coverage, sampling and spatial resolution</summary><p>Clouds, shadows and acquisition timing limit available observations. Seven sampled dates do not cover every heat event. Regional weather does not resolve street-scale conditions. Training on point samples and applying the model to cell averages introduces a scale change that needs further validation.</p></details><details><summary>Tree feasibility and locality boundaries</summary><p>Species, mature canopy, survival, soil, utilities, ownership, road width and available open space are not modelled. Validate planting and cooling recommendations in the field. Reverse-geocoded names are interpretation labels; even the largest cluster is not an official locality boundary.</p></details><details><summary>Future work</summary><p>More cloud-free dates and years; ground stations and mobile surveys; official ward boundaries; population and vulnerability; building geometry and imperviousness; tree species and survival; validated cooling-impact scenarios. Live weather, heat alerts and automatic updates are future capabilities.</p></details></div></section>`}
  function about(){return `<div class="eyebrow">ABOUT THE PROJECT</div><h1 class="about-heading">Understanding Bengaluru’s heat.<br>Planning for a cooler city.</h1><p class="about-subtitle">A student remote-sensing research project by Rohan, connecting satellite and weather data with urban cooling decisions.</p><div class="content-grid"><section class="panel content-card prose"><h2>What this atlas helps you explore</h2><p>The study identifies persistent surface-heat patterns, groups connected hotspots and turns relative cooling priorities into scenario-based interventions. You can inspect each grid cell, compare evidence strength and explore where city-scale planning could begin.</p><p>The atlas presents the final 2026 analysis outputs. It does not run a new model when you filter the map, and it does not display live temperatures.</p><a class="button-primary" href="map.html">Explore the analysis grid ↗</a></section><section class="about-owner"><div class="eyebrow">PROJECT OWNER</div><strong>Rohan</strong><p>ISRO / remote-sensing project context</p><p style="margin-top:18px">Bengaluru study rectangle<br>Final analysis: January–May 2026<br>Historical dataset development: 2022–2026</p><p class="fineprint" style="margin-top:18px">A student research presentation. This site does not establish official ISRO or BBMP affiliation or endorsement.</p></section></div><h2 class="section-heading">Research at a glance</h2><div class="content-grid">${card('SPATIAL COVERAGE','1,320 cells · approximately 1,320 km²',`<p>The complete grid gives a continuous planning view with observation-support distinctions retained. ${number(s.reliable_observation_cells)} cells have at least three sampled dates, ${number(s.limited_plus_v5_cells)} have limited sampled support, and ${number(s.prediction_only_cells)} are model-only in that support classification.</p>`)}${card('COOLING PRIORITIES','330 km² of High + Very High cells',`<p>The 73 connected clusters distinguish large heat corridors from isolated extremes. The combined High and Very High areas have a scenario estimate of ${number(s.high_priority_area_trees)} trees.</p>`)}</div><section class="panel content-card section-heading prose"><h2>Data and map credits</h2><p>Research inputs: Landsat 8 Collection 2 Level 2, Sentinel-2 Surface Reflectance Harmonized, Dynamic World V1, ERA5-Land / ERA5, SRTM elevation and JRC Global Surface Water. Analysis uses Google Earth Engine and Python.</p><p>Interactive map: <a href="https://leafletjs.com/">Leaflet</a>. Basemap and locality geocoding: <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>; reverse geocoding through Nominatim. <a href="https://www.openstreetmap.org/fixthemap">Report a basemap issue</a>.</p><p>Data displayed here comes from the project’s completed grid, ranking and summary exports. <a href="methodology.html">See methods, model comparisons and limitations</a>.</p></section><section class="panel content-card section-heading prose"><h2>Research interpretation</h2><p>This platform provides research-based urban heat and cooling-priority estimates derived from satellite features, meteorological data and machine-learning analysis. Land Surface Temperature is not equivalent to air temperature. Tree counts and cooling recommendations are scenario-based planning estimates and should be validated through field surveys before implementation.</p><p>${sourceExplanation}</p></section>`}
  return {hotspots,renderClusters,methodology,about};
}
